    uint32_t *pGPIOAModeReg = (uint32_t*) (GPIOA_BASE_ADDR + 0x00);
    *pGPIOAModeReg &= ~(0x3 << 16);
    *pGPIOAModeReg |=  (0x2 << 16);

    // 5. Select AF0 (MCO1) for PA8
